358	+    /// Copy a bounded active database into memory using short SQLite backup
359	+    /// steps. Parsing/deduplication then holds no read lock on the live journal.
360	+    /// A constantly changing or busy source can refuse refresh after five seconds.
361	+    pub(crate) fn projection_copy(
362	+        mut self,
363	+        check: &mut dyn FnMut() -> Result<()>,
364	+    ) -> Result<(Self, (u64, u64))> {
365	+        let start = now();
366	+        let deadline = std::time::Instant::now() + Duration::from_secs(5);
367	+        self.conn.busy_timeout(Duration::ZERO)?;
368	+        let mut memory = Connection::open_in_memory()?;
369	+        memory.execute_batch(
370	+            "PRAGMA page_size=4096; PRAGMA max_page_count=8192; PRAGMA temp_store=MEMORY;",
371	+        )?;
372	+        memory.set_limit(rusqlite::limits::Limit::SQLITE_LIMIT_LENGTH, 32768)?;
373	+        {
374	+            let backup = rusqlite::backup::Backup::new(&self.conn, &mut memory)?;
375	+            loop {
376	+                check()?;
377	+                if std::time::Instant::now() >= deadline {
378	+                    return Err(Box::new(SourceBusy));
379	+                }
380	+                let step = backup.step(64)?;
381	+                if !(0..=8192).contains(&backup.progress().pagecount) {
382	+                    return Err(invalid());
383	+                }
384	+                match step {
385	+                    rusqlite::backup::StepResult::Done => break,
386	+                    rusqlite::backup::StepResult::More => std::thread::yield_now(),
387	+                    rusqlite::backup::StepResult::Busy | rusqlite::backup::StepResult::Locked => {
388	+                        std::thread::sleep(Duration::from_millis(1));
389	+                    }
390	+                    _ => return Err(invalid()),
391	+                }
392	+            }
393	+        }
394	+        let end = now();
395	+        self.schema = Self::validate_connection(&memory)?;
396	+        self.conn = memory;
397	+        self.read_only = true;
398	+        Ok((self, (start, end)))
399	+    }
