+/// PO7: exact u64 totals above i64 / 2^53 serialize as decimal strings.
+#[test]
+fn po7_u64_totals_beyond_i64_are_exact_decimal_strings() {
+    let f = Fx::new();
+    let mut j = Journal::open(&f.root).unwrap();
+    for n in 2..=3u64 {
+        let mut x = h(n, 0);
+        x.observed = i64::MAX as u64 - if n == 3 { 10 } else { 0 };
