67	    #[serde(serialize_with = "decimal")]
68	    pub telemetry_dropped_lower_bound: u64,
69	    #[serde(serialize_with = "decimal")]
70	    pub unclosed_sessions: u64,
71	}
72	#[derive(Debug, Clone, Serialize)]
73	pub struct Overview {
74	    pub version: u8,
75	    pub coverage: &'static str,
76	    pub capture_completeness: &'static str,
77	    pub built_at: u64,
78	    pub manifest_sha256: String,
79	    pub active: String,
80	    pub sources: Vec<Source>,
81	    pub totals: Totals,
82	    pub accounted_bytes: usize,
83	    pub memory_limit: usize,
84	}
85	fn cancel(flag: &AtomicBool) -> Result<()> {
86	    if flag.load(Ordering::Relaxed) {
87	        Err(Box::new(Failure::Cancelled))
88	    } else {
89	        Ok(())
90	    }
91	}
92	fn cost(row: &Observation) -> Result<usize> {
93	    // Includes serialized strings, map nodes, duplicated identity keys, allocator
94	    // slack and fixed row storage. Refuse before retaining a new row.
95	    serde_json::to_vec(row)?
96	        .len()
97	        .checked_add(1024)
98	        .ok_or_else(|| Box::new(Failure::Overflow) as _)
99	}
100	struct Budget {
101	    used: usize,
102	    limit: usize,
103	}
104	impl Budget {
105	    fn add(&mut self, n: usize) -> Result<()> {
106	        let next = self.used.checked_add(n).ok_or(Failure::Overflow)?;
107	        if next > self.limit {
108	            return Err(Box::new(Failure::Capacity("memory")));
109	        }
110	        self.used = next;
111	        Ok(())
112	    }
113	}
114	struct Selected {
115	    row: Observation,
116	    cost: usize,
117	}
118	struct Aggregate {
119	    attempts: BTreeMap<String, Selected>,
120	    sessions: BTreeMap<String, Selected>,
121	    limits: Limits,
122	}
123	impl Aggregate {
124	    fn new(limits: Limits) -> Self {
125	        Self {
126	            attempts: BTreeMap::new(),
127	            sessions: BTreeMap::new(),
128	            limits,
129	        }
130	    }
131	    fn add(&mut self, row: Observation, budget: &mut Budget) -> Result<()> {
132	        let n = cost(&row)?;
133	        let (key, map, limit, label) = match &row {
134	            Observation::Attempt { health, .. } => (
135	                health.attempt.clone(),
136	                &mut self.attempts,
137	                self.limits.attempts,
138	                "attempts",
139	            ),
140	            Observation::Session { id, .. } => (
141	                id.clone(),
142	                &mut self.sessions,
143	                self.limits.sessions,
144	                "sessions",
145	            ),
146	        };
147	        if let Some(old) = map.get(&key) {
148	            let dominates = match (&row, &old.row) {
149	                (
150	                    Observation::Attempt { health: new, .. },
151	                    Observation::Attempt { health: old, .. },
152	                ) => operations::dominates(new, old),
153	                (
154	                    Observation::Session {
155	                        dropped: new,
156	                        clean: nc,
157	                        ..
158	                    },
159	                    Observation::Session {
160	                        dropped: old,
161	                        clean: oc,
162	                        ..
163	                    },
164	                ) => new >= old && (!oc || *nc),
165	                _ => false,
166	            };
167	            if !dominates {
168	                return Err(Box::new(Failure::Conflict));
169	            }
170	            budget.used -= old.cost;
171	        } else if map.len() >= limit {
172	            return Err(Box::new(Failure::Capacity(label)));
173	        }
174	        budget.add(n)?;
175	        map.insert(key, Selected { row, cost: n });
176	        Ok(())
177	    }
178	    fn totals(&self) -> Result<Totals> {
179	        let mut t = Totals {
180	            attempts: self.attempts.len() as u64,
181	            sessions: self.sessions.len() as u64,
182	            observed: 0,
183	            locally_queued: 0,
184	            unconfirmed: 0,
185	            attempts_with_gaps: 0,
186	            telemetry_dropped_lower_bound: 0,
187	            unclosed_sessions: 0,
188	        };
189	        fn add(dst: &mut u64, n: u64) -> Result<()> {
190	            *dst = dst.checked_add(n).ok_or(Failure::Overflow)?;
191	            Ok(())
192	        }
193	        for selected in self.attempts.values() {
194	            let Observation::Attempt { health, .. } = &selected.row else {
195	                unreachable!()
196	            };
197	            add(&mut t.observed, health.observed)?;
198	            add(&mut t.locally_queued, health.locally_queued)?;
199	            add(&mut t.unconfirmed, health.unconfirmed)?;
200	            add(&mut t.attempts_with_gaps, u64::from(health.recording_gap))?;
201	        }
202	        for selected in self.sessions.values() {
203	            let Observation::Session { dropped, clean, .. } = &selected.row else {
204	                unreachable!()
205	            };
206	            add(&mut t.telemetry_dropped_lower_bound, *dropped)?;
207	            add(&mut t.unclosed_sessions, u64::from(!clean))?;
208	        }
209	        Ok(t)
210	    }
211	}
212	// Bounded streaming hash, no 32-MiB plaintext file copy. The shared collection
213	// lock protects membership/rotation; a sealed file must match its committed hash.
214	fn sealed_hash(path: &Path, flag: &AtomicBool) -> Result<String> {
215	    let mut file = File::open(path)?;
216	    let mut digest = Sha256::new();
217	    let mut bytes = 0u64;
218	    let mut buffer = [0; 65536];
219	    loop {
220	        cancel(flag)?;
221	        let n = file.read(&mut buffer)?;
222	        if n == 0 {
223	            break;
224	        }
225	        bytes += n as u64;
226	        if bytes > SOURCE_LIMIT {
227	            return Err(invalid());
228	        }
229	        digest.update(&buffer[..n]);
230	    }
231	    Ok(crate::evidence_service::hex(&digest.finalize()))
232	}
233	fn source(
234	    root: &Path,
235	    g: &Generation,
236	    binding: &Binding,
237	    flag: &AtomicBool,
238	    visit: &mut dyn FnMut(Observation) -> Result<()>,
239	    hook: &mut dyn FnMut(Boundary) -> Result<()>,
240	) -> Result<Source> {
241	    cancel(flag)?;
242	    let path = generation_path(root, &g.id);
243	    private(&path, false, SOURCE_LIMIT)?;
244	    // All collection generations have an existing lifetime lock. Refuse missing
245	    // coordination files rather than letting a read projection create one.
246	    let mut lock_path = path.as_os_str().to_os_string();
247	    lock_path.push(".lock");
248	    private(Path::new(&lock_path), false, 0)?;
249	    if let Some(expected) = &g.sealed_sha256 {
250	        sidecars_absent(&path)?;
251	        if &sealed_hash(&path, flag)? != expected {
252	            return Err(invalid());
253	        }
254	    }
255	    let journal = Journal::open_file(&path, false, true)?;
256	    let (journal, active_window) = if g.sealed_sha256.is_none() {
257	        let (copy, window) = journal.projection_copy(&mut || cancel(flag))?;
258	        (copy, Some(window))
259	    } else {
260	        (journal, None)
261	    };
262	    let expected = (
263	        binding.spool.clone(),
264	        binding.writer.clone(),
265	        binding.scope.clone(),
266	        binding.audience.clone(),
267	    );
268	    let mut snapshot = journal.scan_projection(&expected, &mut |row| {
269	        cancel(flag)?;
270	        visit(row)
271	    })?;
272	    if let Some((start, end)) = active_window {
273	        snapshot.started_at = start;
274	        snapshot.finished_at = end;
275	    }
276	    hook(Boundary::SourceRowsRead)?;
277	    // Recheck sealed bytes after the SQLite read so a changed source is never
278	    // promoted merely because it passed a pre-open hash.
279	    if let Some(expected) = &g.sealed_sha256 {
280	        if &sealed_hash(&path, flag)? != expected {
281	            return Err(invalid());
282	        }
283	    }
284	    if g.sealed_sha256.is_some() {
285	        snapshot.worker = None;
286	    }
287	    Ok(Source {
288	        generation: g.id.clone(),
289	        sealed_sha256: g.sealed_sha256.clone(),
290	        snapshot,
291	    })
292	}
293	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
294	pub enum Boundary {
295	    MembershipPinned,
296	    SourceRowsRead,
297	    ActiveRead,
298	    GenerationRead,
299	    BeforePublish,
300	}
301	/// Explicit, synchronous, owner-side refresh. Ordinary status polling must not
302	/// call this function. The hook is a deterministic test seam outside SQLite reads.
303	pub fn build(root: &Path, flag: &AtomicBool, limits: Limits) -> Result<Overview> {
304	    build_observed(root, flag, limits, &mut |_| Ok(()))
305	}
306	pub fn build_observed(
307	    root: &Path,
308	    flag: &AtomicBool,
309	    limits: Limits,
310	    hook: &mut dyn FnMut(Boundary) -> Result<()>,
311	) -> Result<Overview> {
312	    cancel(flag)?;
313	    let max = Limits::default();
314	    if limits.attempts > max.attempts || limits.sessions > max.sessions || limits.bytes > max.bytes
315	    {
316	        return Err(Box::new(Failure::Capacity("configured bound")));
317	    }
318	    let _held = lock(root, false)?;
319	    let (m, manifest_sha256) = manifest_snapshot(root)?;
320	    hook(Boundary::MembershipPinned)?;
321	    let mut budget = Budget {
322	        used: 0,
323	        limit: limits.bytes,
324	    };
325	    budget.add(WORKING_RESERVE)?;
326	    let mut active_rows = Vec::new();
327	    let active = m.generations.last().ok_or_else(invalid)?;
328	    let mut attempt_count = 0usize;
329	    let mut session_count = 0usize;
330	    let active_source = source(
331	        root,
332	        active,
333	        &m.binding,
334	        flag,
335	        &mut |row| {
336	            match &row {
337	                Observation::Attempt { .. } => {
338	                    attempt_count += 1;
339	                    if attempt_count > limits.attempts {
340	                        return Err(Box::new(Failure::Capacity("attempts")));
341	                    }
342	                }
343	                Observation::Session { .. } => {
344	                    session_count += 1;
345	                    if session_count > limits.sessions {
346	                        return Err(Box::new(Failure::Capacity("sessions")));
347	                    }
348	                }
349	            }
350	            budget.add(cost(&row)?)?;
351	            active_rows.push(row);
352	            Ok(())
353	        },
354	        hook,
355	    )?;
356	    hook(Boundary::ActiveRead)?;
357	    let mut aggregate = Aggregate::new(limits);
358	    let mut sources = Vec::new();
359	    budget.add(serde_json::to_vec(&active_source)?.len() + 1024)?;
360	    for g in &m.generations[..m.generations.len() - 1] {
361	        let sampled = source(
362	            root,
363	            g,
364	            &m.binding,
365	            flag,
366	            &mut |row| aggregate.add(row, &mut budget),
367	            hook,
368	        )?;
369	        budget.add(serde_json::to_vec(&sampled)?.len() + 1024)?;
370	        sources.push(sampled);
371	        hook(Boundary::GenerationRead)?;
372	    }
373	    // Apply the pinned active snapshot last, so every chronological cumulative
374	    // transition is checked, even if an eventual larger value dominates both.
375	    for row in active_rows {
376	        cancel(flag)?;
377	        budget.used -= cost(&row)?;
378	        aggregate.add(row, &mut budget)?;
379	    }
380	    sources.push(active_source);
381	    let totals = aggregate.totals()?;
382	    hook(Boundary::BeforePublish)?;
383	    cancel(flag)?;
384	    if manifest_snapshot(root)?.1 != manifest_sha256 {
385	        return Err(invalid());
386	    }
387	    Ok(Overview {
388	        version: 1,
389	        coverage: "observations-only",
390	        capture_completeness: "unknown",
391	        built_at: operations::now(),
392	        manifest_sha256,
393	        active: m.active,
394	        sources,
395	        totals,
396	        accounted_bytes: budget.used,
397	        memory_limit: limits.bytes,
398	    })
399	}
400	
401	fn source_busy(error: &(dyn std::error::Error + Send + Sync + 'static)) -> bool {
402	    error.is::<operations::projection::SourceBusy>()
403	        || matches!(
404	            error.downcast_ref::<fs4::TryLockError>(),
405	            Some(fs4::TryLockError::WouldBlock)
406	        )
407	        || error
408	            .downcast_ref::<std::io::Error>()
409	            .is_some_and(|e| e.kind() == std::io::ErrorKind::WouldBlock)
410	        || matches!(error.downcast_ref::<rusqlite::Error>(),Some(rusqlite::Error::SqliteFailure(e,_)) if matches!(e.code,rusqlite::ErrorCode::DatabaseBusy|rusqlite::ErrorCode::DatabaseLocked))
411	}
412	
413	/// Published memory only. A prior result stays explicitly associated with its
414	/// original job/snapshot while a new refresh runs, fails or is cancelled.
415	#[derive(Debug, Clone, Serialize)]
416	pub struct Published {
417	    pub version: u8,
418	    pub state: &'static str,
419	    pub job: u64,
420	    pub reason: Option<String>,
421	    pub last_job: Option<u64>,
422	    pub last: Option<Overview>,
423	}
424	struct Control {
425	    handle: Option<std::thread::JoinHandle<()>>,
426	    cancel: std::sync::Arc<AtomicBool>,
427	    next: u64,
428	}
429	pub struct Manager {
430	    published: std::sync::Arc<std::sync::Mutex<Published>>,
431	    control: std::sync::Mutex<Control>,
432	}
433	impl Default for Manager {
434	    fn default() -> Self {
435	        Self::new()
436	    }
437	}
438	impl Manager {
439	    pub fn new() -> Self {
440	        Self {
441	            published: std::sync::Arc::new(std::sync::Mutex::new(Published {
442	                version: 1,
443	                state: "unavailable",
444	                job: 0,
445	                reason: None,
446	                last_job: None,
447	                last: None,
448	            })),
449	            control: std::sync::Mutex::new(Control {
450	                handle: None,
451	                cancel: std::sync::Arc::new(AtomicBool::new(false)),
452	                next: 0,
453	            }),
454	        }
455	    }
456	    pub fn status(&self) -> Published {
457	        self.published.lock().unwrap().clone()
458	    }
459	    pub fn refresh(&self, root: PathBuf) -> Result<Published> {
460	        self.refresh_observed(root, Limits::default(), |_| Ok(()))
461	    }
462	    /// Deterministic test seam. Hooks execute only outside SQLite snapshots.
463	    pub fn refresh_observed(
464	        &self,
465	        root: PathBuf,
466	        limits: Limits,
467	        mut hook: impl FnMut(Boundary) -> Result<()> + Send + 'static,
468	    ) -> Result<Published> {
469	        let mut control = self.control.lock().unwrap();
470	        if control.handle.as_ref().is_some_and(|h| !h.is_finished()) {
471	            return Ok(self.status());
472	        }
473	        if let Some(previous) = control.handle.take() {
474	            let _ = previous.join();
475	        }
476	        control.next = control.next.checked_add(1).ok_or(Failure::Overflow)?;
477	        let job = control.next;
478	        let cancel = std::sync::Arc::new(AtomicBool::new(false));
479	        control.cancel = cancel.clone();
480	        {
481	            let mut state = self.published.lock().unwrap();
482	            state.state = "building";
483	            state.job = job;
484	            state.reason = None;
485	        }
486	        let published = self.published.clone();
487	        match std::thread::Builder::new()
488	            .name("kan-operations-overview".into())
489	            .spawn(move || {
490	                let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
491	                    build_observed(&root, &cancel, limits, &mut hook)
492	                }));
493	                let mut state = published.lock().unwrap();
494	                if cancel.load(Ordering::Relaxed) {
495	                    state.state = "cancelled";
496	                    state.reason = None;
497	                } else {
498	                    match result {
499	                        Ok(Ok(overview)) => {
500	                            state.state = "completed";
501	                            state.last_job = Some(job);
502	                            state.last = Some(overview);
503	                            state.reason = None;
504	                        }
505	                        Ok(Err(error)) => {
506	                            state.state = if matches!(
507	                                error.downcast_ref::<Failure>(),
508	                                Some(Failure::Capacity(_))
509	                            ) {
510	                                "capacity-limited"
511	                            } else {
512	                                "failed"
513	                            };
514	                            state.reason = Some(match error.downcast_ref::<Failure>() {
515	                                Some(Failure::Capacity(bound)) => format!("{bound} bound reached"),
516	                                Some(Failure::Conflict) => {
517	                                    "conflicting cumulative observations".into()
518	                                }
519	                                Some(Failure::Overflow) => "counter overflow".into(),
520	                                _ if source_busy(error.as_ref()) => {
521	                                    "source busy or in use; retry refresh".into()
522	                                }
523	                                _ => "source invalid or unavailable".into(),
524	                            });
525	                        }
526	                        Err(_) => {
527	                            state.state = "failed";
528	                            state.reason = Some("overview worker failed".into());
529	                        }
530	                    }
531	                }
532	            }) {
533	            Ok(handle) => control.handle = Some(handle),
534	            Err(error) => {
535	                let mut state = self.published.lock().unwrap();
536	                state.state = "failed";
537	                state.reason = Some("overview worker unavailable".into());
538	                return Err(error.into());
539	            }
540	        }
541	        Ok(self.status())
542	    }
543	    pub fn cancel(&self) -> Published {
544	        let control = self.control.lock().unwrap();
545	        if control.handle.as_ref().is_some_and(|h| !h.is_finished()) {
546	            control.cancel.store(true, Ordering::Relaxed);
547	            let mut state = self.published.lock().unwrap();
548	            if state.state == "building" {
549	                state.state = "cancelling";
550	            }
551	        }
552	        self.status()
553	    }
554	}
555	impl Drop for Manager {
556	    fn drop(&mut self) {
557	        let control = self.control.get_mut().unwrap();
558	        control.cancel.store(true, Ordering::Relaxed);
559	        if let Some(handle) = control.handle.take() {
560	            let _ = handle.join();
561	        }
562	    }
563	}
