154	// Caller owns a transaction. Constant working memory; currently a full scan.
155	// `through` excludes a new, not-yet-attested row inside admission's transaction.
156	fn audit_prefix(
157	    conn: &Connection,
158	    binding: &Binding,
159	    through: u64,
160	    target: Option<&Cid>,
161	) -> Result<(Frontier, Option<Verified>)> {
162	    check_binding(conn, binding)?;
163	    let count: i64 = conn.query_row("SELECT count(*) FROM attestations", [], |r| r.get(0))?;
164	    if u64::try_from(count).ok() != Some(through) {
165	        return Err(corrupt("attestation cardinality"));
166	    }
167	    let mut frontier = Frontier::default();
168	    let mut selected = None;
169	    let mut historical_issuer: Option<String> = None;
170	    let mut admitted = false;
171	    let mut stmt = conn.prepare(&format!(
172	        "{RAW_COMMITS} WHERE sequence<=? ORDER BY sequence"
173	    ))?;
174	    let mut rows =
175	        stmt.query([i64::try_from(through).map_err(|_| Error::Invalid("sequence overflow"))?])?;
176	    while let Some(row) = rows.next()? {
177	        let record = raw_commit(row)?;
178	        if record.sequence != frontier.through + 1 {
179	            return Err(corrupt("noncontiguous attestation chain"));
180	        }
181	        let verified = proof::verify(
182	            &envelope(conn, record.sequence)?,
183	            &binding.context(),
184	            &record.manifest,
185	            &record.receipt,
186	            &frontier,
187	        )
188	        .map_err(|_| corrupt("invalid attestation chain"))?;
189	        let signed = retained(conn, &record, binding)?;
190	        match verified.purpose() {
191	            Purpose::Admitted => {
192	                admitted = true;
193	                if signed.request.audience != binding.issuer {
194	                    return Err(corrupt("admitted request audience"));
195	                }
196	            }
197	            Purpose::RetainedVerified => {
198	                if admitted
199	                    || historical_issuer
200	                        .as_ref()
201	                        .is_some_and(|h| h != &signed.request.audience)
202	                {
203	                    return Err(corrupt("retained-verified prefix"));
204	                }
205	                historical_issuer = Some(signed.request.audience);
206	            }
207	        }
208	        frontier = verified.frontier().clone();
209	        if target == Some(record.manifest.cid()) {
210	            selected = Some(verified);
211	        }
212	    }
213	    if frontier.through != through {
214	        return Err(corrupt("attestation chain length"));
215	    }
216	    Ok((frontier, selected))
217	}
