270	            ledger.conn.set_limit(
271	                rusqlite::limits::Limit::SQLITE_LIMIT_LENGTH,
272	                RECOVERY_SQLITE_LENGTH_LIMIT,
273	            )?;
274	            Self { ledger, binding }
275	        };
276	        std::fs::File::open(root)?.sync_all()?;
277	        std::fs::File::open(parent_directory(root))?.sync_all()?;
278	        Ok(archive)
279	    }
280	    /// Full standalone backup. A failure may leave an incomplete or complete
281	    /// output; use a fresh destination, never overwrite or promote automatically.
282	    pub fn backup(&self, destination: &Path) -> Result<Verification> {
283	        self.backup_observed(destination, &mut |_| {})
284	    }
285	    pub fn backup_observed(
286	        &self,
287	        destination: &Path,
288	        observe: &mut dyn FnMut(BackupBoundary),
289	    ) -> Result<Verification> {
290	        let destination = self.ledger.backup_copy(destination, observe)?;
291	        Self::verify_file(&destination, self.binding.clone())
292	    }
293	    /// Full audit of a standalone profile-2 file against owner configuration.
294	    /// Read-only SQLite can initialize its declared WAL/SHM coordination files.
295	    pub fn verify_file(path: &Path, binding: Binding) -> Result<Verification> {
296	        let reader = Recovery::open(path, binding)?;
297	        reader.reader.ledger.check_write_profile(true)?;
298	        let base = reader.reader.ledger.verify_contents()?;
299	        verify_contents(&reader.reader.ledger, &reader.binding, &base)?;
300	        Ok(base)
301	    }
302	    pub fn binding(&self) -> &Binding {
303	        &self.binding
304	    }
305	    pub fn verify(&self) -> Result<Frontier> {
306	        self.verify_for(None).map(|(frontier, _)| frontier)
307	    }
308	    fn verify_for(&self, target: Option<&Cid>) -> Result<(Frontier, Option<Verified>)> {
309	        let tx = self.ledger.conn.unchecked_transaction()?;
310	        let base = self.ledger.verify_contents()?;
311	        let (frontier, selected) = audit_prefix(&tx, &self.binding, base.snapshot.through, target)?;
312	        if frontier.manifest != base.snapshot.tip {
313	            return Err(corrupt("attestation tip"));
314	        }
315	        tx.commit()?;
316	        Ok((frontier, selected))
317	    }
318	    /// Owner-side admission. The caller supplies a current trusted grant; remote
319	    /// callers must never be allowed to supply or choose this grant themselves.
320	    pub fn admit(
321	        &mut self,
322	        bytes: &[u8],
323	        signer: &Identity,
324	        grant: &Grant,
325	        now: u64,
326	    ) -> std::result::Result<Admission, Failure> {
327	        self.admit_observed(bytes, signer, grant, now, &mut |_| {})
328	    }
329	    /// Fault harness only: callbacks cannot establish durability.
330	    pub fn admit_observed(
331	        &mut self,
332	        bytes: &[u8],
333	        signer: &Identity,
334	        grant: &Grant,
335	        now: u64,
336	        observe: &mut dyn FnMut(Boundary),
337	    ) -> std::result::Result<Admission, Failure> {
338	        let signed = SignedRequest::decode(bytes)?;
339	        if !grant.append
340	            || grant.principal != signed.request.principal
341	            || signed.request.scope != service::hex(&self.binding.scope)
342	            || signed.request.audience != self.binding.issuer
343	            || signer.did().as_str() != self.binding.issuer
344	        {
345	            return Err(Failure::AccessLimited);
346	        }
347	        let manifest = service::append_manifest(bytes)?;
348	        let receipt = service::receipt(&manifest, &self.binding.issuer, now)?;
349	        let (previous, duplicate_proof) = self.verify_for(Some(manifest.cid()))?;
350	        self.ledger.stage_observed(bytes, observe)?;
351	        let expected = Snapshot {
352	            through: previous.through,
353	            tip: previous.manifest.clone(),
354	        };
355	        let binding = &self.binding;
356	        let mut result = None;
357	        let mut hook = |tx: &rusqlite::Transaction<'_>,
358	                        row: &Committed,
359	                        observe: &mut dyn FnMut(Boundary)|
360	         -> Result<()> {
361	            // All archive mutations through this API append. Recheck both tips
362	            // and proof cardinality under the immediate writer transaction; a
363	            // raw append or same-height replacement cannot cross this fence.
364	            check_binding(tx, binding)?;
365	            let count: i64 = tx.query_row("SELECT count(*) FROM attestations", [], |r| r.get(0))?;
366	            if u64::try_from(count).ok() != Some(previous.through) {
367	                return Err(Error::Conflict("attestation audit frontier"));
368	            }
369	            if previous.through > 0 {
370	                let tip = record(tx, previous.through)?;
371	                proof::verify_at(
372	                    &envelope(tx, previous.through)?,
373	                    &binding.context(),
374	                    &tip.manifest,
375	                    &tip.receipt,
376	                    &previous,
377	                )
378	                .map_err(|_| Error::Conflict("attestation audit frontier"))?;
379	            }
380	            let verified = if row.duplicate {
381	                let old = duplicate_proof
382	                    .as_ref()
383	                    .ok_or_else(|| corrupt("unaudited retry"))?;
384	                if old.frontier().through != row.sequence
385	                    || old.frontier().manifest.as_ref() != Some(row.manifest.cid())
386	                    || envelope(tx, row.sequence)? != old.bytes()
387	                {
388	                    return Err(Error::Conflict("retry proof changed"));
389	                }
390	                // Recheck exact receipt binding against the previously verified proof.
391	                proof::verify_at(
392	                    old.bytes(),
393	                    &binding.context(),
394	                    &row.manifest,
395	                    &row.receipt,
396	                    old.frontier(),
397	                )
398	                .map_err(|_| Error::Conflict("retry receipt changed"))?;
399	                if old.purpose() != Purpose::Admitted {
400	                    return Err(Error::Conflict(
401	                        "imported retry requires explicit confirmation",
402	                    ));
403	                }
404	                old.clone()
405	            } else {
406	                if row.sequence != previous.through + 1 {
407	                    return Err(corrupt("new attestation sequence"));
408	                }
409	                let proof = proof::issue(
410	                    signer,
411	                    &binding.context(),
412	                    &row.manifest,
413	                    &row.receipt,
414	                    &previous,
415	                    Purpose::Admitted,
416	                    now.checked_mul(1000).ok_or(Error::Invalid("timestamp"))?,
417	                )?;
418	                observe(Boundary::AttestationSigned);
419	                // surface-write: evidence-proof-sqlite:attestations
420	                crate::persistence::insert_evidence_proof(
421	                    crate::persistence::SurfaceWrite::EvidenceAttestation,
422	                    tx,
423	                    i64::try_from(row.sequence).map_err(|_| Error::Invalid("sequence overflow"))?,
424	                    proof.bytes(),
425	                )?;
426	                observe(Boundary::AttestationInserted);
427	                proof
428	            };
429	            result = Some(verified);
430	            Ok(())
431	        };
432	        let record = self.ledger.commit_inner(
433	            manifest.bytes(),
434	            receipt.bytes(),
435	            observe,
436	            true,
437	            Some(&expected),
438	            Some(&mut hook),
439	        )?;
440	        Ok(Admission {
441	            record,
442	            attestation: result.ok_or(Failure::Corrupt)?,
443	        })
444	    }
445	}
446	
447	/// Read-only pinned source for a full proof-preserving rebuild. Opening does not
448	/// certify raw contents; successful rebuild verifies all metadata, proofs and
449	/// payloads. No degraded or metadata-only success is returned by this API.
450	pub struct Recovery {
451	    reader: RecoveryReader,
452	    binding: Binding,
453	}
454	impl Recovery {
455	    pub fn open(path: &Path, binding: Binding) -> Result<Self> {
456	        binding.validate()?;
457	        let reader = RecoveryReader::open_profile(path, 2)?;
458	        check_binding(&reader.ledger.conn, &binding)?;
459	        Ok(Self { reader, binding })
460	    }
461	    pub fn rebuild(&self, destination: &Path) -> Result<Verification> {
462	        self.rebuild_observed(destination, &mut |_| {})
463	    }
464	    pub fn rebuild_observed(
465	        &self,
466	        destination: &Path,
467	        observe: &mut dyn FnMut(RecoveryBoundary),
468	    ) -> Result<Verification> {
469	        self.reader
470	            .rebuild_profile(destination, observe, Some(&self.binding))
471	    }
472	}
473	pub(super) fn check_copy_source(conn: &Connection, binding: &Binding, through: u64) -> Result<()> {
474	    check_binding(conn, binding)?;
475	    let count: i64 = conn.query_row("SELECT count(*) FROM attestations", [], |r| r.get(0))?;
476	    if u64::try_from(count).ok() != Some(through) {
477	        return Err(corrupt("attestation cardinality"));
478	    }
479	    Ok(())
480	}
481	pub(super) fn copy_proof(
482	    source: &Connection,
483	    target: &rusqlite::Transaction<'_>,
484	    sequence: u64,
485	) -> Result<()> {
486	    let bytes = envelope(source, sequence)?;
487	    // surface-write: evidence-proof-sqlite:attestations
488	    crate::persistence::insert_evidence_proof(
489	        crate::persistence::SurfaceWrite::EvidenceAttestation,
490	        target,
491	        i64::try_from(sequence).map_err(|_| Error::Invalid("sequence overflow"))?,
492	        &bytes,
493	    )?;
494	    Ok(())
495	}
496	pub(super) fn verify_contents(
497	    ledger: &Ledger,
498	    binding: &Binding,
499	    base: &Verification,
500	) -> Result<()> {
501	    let (frontier, _) = audit_prefix(&ledger.conn, binding, base.snapshot.through, None)?;
502	    if frontier.manifest != base.snapshot.tip {
503	        return Err(corrupt("attestation tip"));
504	    }
505	    Ok(())
506	}
