168	    /// Open a database FILE, including a standalone backup, without consulting
169	    /// derived fields. SQLite must still be able to read its schema/raw tables.
170	    /// WAL mode may initialize coordination sidecars; read-only media without
171	    /// usable sidecars and hot rollback journals fail closed. Preserve all source
172	    /// media together and perform any crash recovery on a separate writable copy.
173	    pub fn open(path: &Path) -> Result<Self> {
174	        Self::open_profile(path, 1)
175	    }
176	    fn open_profile(path: &Path, profile: i64) -> Result<Self> {
177	        private_file(path)?;
178	        let source = std::fs::canonicalize(path)?;
179	        let ledger = Ledger {
180	            // surface-write: evidence-recovery-source:database-wal,evidence-recovery-source:database-shm
181	            conn: crate::persistence::open_sqlite_recovery_source(
182	                crate::persistence::SurfaceWrite::EvidenceRecoverySource,
183	                &source,
184	            )?,
185	        };
186	        ledger.conn.set_limit(
187	            rusqlite::limits::Limit::SQLITE_LIMIT_LENGTH,
188	            RECOVERY_SQLITE_LENGTH_LIMIT,
189	        )?;
190	        ledger.conn.busy_timeout(Duration::from_secs(5))?;
191	        ledger.conn.execute_batch("PRAGMA query_only=ON; BEGIN;")?;
192	        // Reading the profile pins the transaction before the handle escapes.
193	        ledger.check_profile(profile)?;
194	        Ok(Self { ledger, source })
195	    }
