370	fn sqlite_paths(path: &Path) -> Vec<PathBuf> {
371	    let mut paths = vec![path.to_path_buf()];
372	    for suffix in ["-journal", "-wal", "-shm"] {
373	        let mut name = path.as_os_str().to_os_string();
374	        name.push(suffix);
375	        paths.push(PathBuf::from(name));
376	    }
377	    paths
378	}
