380	fn same_existing_file(a: &Path, b: &Path) -> bool {
381	    #[cfg(unix)]
382	    {
383	        use std::os::unix::fs::MetadataExt;
384	        matches!((std::fs::metadata(a), std::fs::metadata(b)), (Ok(a), Ok(b)) if a.dev() == b.dev() && a.ino() == b.ino())
385	    }
386	    #[cfg(not(unix))]
387	    {
388	        matches!((std::fs::canonicalize(a), std::fs::canonicalize(b)), (Ok(a), Ok(b)) if a == b)
389	    }
390	}
