392	fn sqlite_destination(source: &Path, destination: &Path) -> Result<PathBuf> {
393	    let parent = std::fs::canonicalize(parent_directory(destination))?;
394	    let name = destination
395	        .file_name()
396	        .ok_or(Error::Invalid("destination filename"))?;
397	    let destination = parent.join(name);
398	    let target_paths = sqlite_paths(&destination);
399	    let source_paths = sqlite_paths(source);
400	    // Conservative ASCII case comparison also protects case-insensitive volumes.
401	    if target_paths.iter().any(|target| {
402	        source_paths.iter().any(|source| {
403	            target
404	                .as_os_str()
405	                .as_encoded_bytes()
406	                .eq_ignore_ascii_case(source.as_os_str().as_encoded_bytes())
407	        })
408	    }) {
409	        return Err(Error::Invalid("destination overlaps source SQLite files"));
410	    }
411	    // Resolve an existing base through filesystem aliases (including Unicode
412	    // spelling/case aliases on macOS and hard links on Unix), before a sidecar
413	    // that does not exist yet can be created under that base's name.
414	    if let Some(name) = name.to_str() {
415	        for suffix in ["-journal", "-wal", "-shm"] {
416	            if name.len() >= suffix.len()
417	                && name.as_bytes()[name.len() - suffix.len()..]
418	                    .eq_ignore_ascii_case(suffix.as_bytes())
419	            {
420	                let base = parent.join(&name[..name.len() - suffix.len()]);
421	                if same_existing_file(&base, source) {
422	                    return Err(Error::Invalid("destination aliases source SQLite sidecar"));
423	                }
424	            }
425	        }
426	    }
427	    unused_sqlite_sidecars(&destination)?;
428	    Ok(destination)
429	}
