431	fn unused_sqlite_sidecars(destination: &Path) -> Result<()> {
432	    // A new main filename alone is insufficient: SQLite owns these sibling names.
433	    for path in sqlite_paths(destination).iter().skip(1) {
434	        match std::fs::symlink_metadata(path) {
435	            Ok(_) => return Err(Error::Invalid("destination SQLite sidecar already exists")),
436	            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
437	            Err(e) => return Err(e.into()),
438	        }
439	    }
440	    Ok(())
441	}
