fn manager_finish(m: &Manager) -> overview::Published {
    let deadline = Instant::now() + Duration::from_secs(20);
    loop {
        let s = m.status();
        if !["building", "cancelling"].contains(&s.state) {
            return s;
        }
        assert!(Instant::now() < deadline);
        std::thread::sleep(Duration::from_millis(5));
    }
}

