    let child = spawn("record", &[("KAN_REVIEW_ROOT", f.root.display().to_string()), ("KAN_REVIEW_READY", ready.display().to_string()), ("KAN_REVIEW_DURATION_MS", "12000".into()), ("KAN_REVIEW_INTERVAL_MS", "0".into()), ("KAN_REVIEW_START", "2000000".into())]);
